<?php
declare(strict_types=1);define('CWP_BOOT',true);require __DIR__.'/app/core.php';boot();require __DIR__.'/app/view.php';require __DIR__.'/app/growth.php';require __DIR__.'/app/workspace.php';require __DIR__.'/app/admin-view.php';require __DIR__.'/app/support-admin.php';header('X-Robots-Tag: noindex, nofollow');header('Referrer-Policy: no-referrer');
$error='';$supportRequested=array_key_exists('support',$_GET);$supportId=is_string($_GET['support']??null)?$_GET['support']:'';
if($supportRequested){
 if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??null)==='support_end'){
  try{support_check_csrf($supportId);support_end($supportId);redirect(admin_url('support'));}catch(Throwable){support_unavailable();}
 }
 $context=support_resolve($supportId);if(!$context)support_unavailable();$GLOBALS['cwp_support']=$context;
}
$client=studio_client();$jobId=isset($_GET['job'])&&is_string($_GET['job'])?(int)$_GET['job']:0;$invite=is_string($_GET['invite']??null)?$_GET['invite']:'';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{if($supportRequested)support_check_csrf($supportId);else check_csrf();if(!studio_ready())throw new RuntimeException('The client workspace has not been enabled. Please contact the studio.');$action=posted('action',40);
 if(support_current()){
  if(!in_array($action,['message','upload'],true)){support_record('action.blocked','portal','','denied');throw new RuntimeException('This action is blocked during support. Client decisions, payments and security changes require the proper independent workflow.');}
  if(!consume_rate('support-action-'.support_current()['actor']['id'],30,3600))throw new RuntimeException('Please wait before making more support changes.');
  if($action==='message')support_message($supportId,$jobId,posted('body',5000));else support_upload($supportId,$jobId);
  flash('Saved as Studio support.');redirect(studio_url(['job'=>$jobId]));
 }
 elseif($action==='activate'){$password=posted('password',72);if($password!==posted('confirm_password',72))throw new InvalidArgumentException('Passwords do not match.');if(!consume_rate(ip_key('client-activate'),10,900))throw new RuntimeException('Please wait before trying again.');studio_activate(posted('invite',64),$password);flash('Your password is saved. Sign in below.');redirect(studio_url());}
 elseif($action==='login'){studio_login(strtolower(posted('email',190)),posted('password',1000));redirect(studio_url());}
 elseif($action==='logout'){unset($_SESSION['client_id'],$_SESSION['client_auth'],$_SESSION['client_last'],$_SESSION['client_login']);session_regenerate_id(true);redirect(studio_url());}
 else{if(!$client)throw new RuntimeException('Sign in to continue.');$job=studio_job($jobId,(int)$client['id']);
 if($action==='message'){$body=posted('body',5000);if(strlen($body)<2)throw new InvalidArgumentException('Write a message.');if(!consume_rate(ip_key('client-message'),30,3600))throw new RuntimeException('Please wait before sending more messages.');query('INSERT INTO '.table('studio_messages').' (job_id,author_type,author_id,body,created_at) VALUES (?,?,?,?,?)',[$jobId,'client',$client['id'],$body,gmdate('Y-m-d H:i:s')]);flash('Message saved.');}
 elseif($action==='decision'){if(posted('confirm',1)!=='1')throw new InvalidArgumentException('Confirm the decision for this version.');$version=(int)posted('version',12);if(!one('SELECT id FROM '.table('studio_versions').' WHERE id=? AND job_id=?',[$version,$jobId]))throw new InvalidArgumentException('Review not found.');studio_decide((int)$client['id'],$version,posted('choice',20),posted('feedback',5000));flash('Your decision was recorded against that version.');}
 elseif($action==='upload'){if(!consume_rate(ip_key('client-upload'),10,3600))throw new RuntimeException('Upload limit reached.');studio_upload($jobId,'client');flash('File saved privately.');}
 else throw new InvalidArgumentException('Unknown action.');redirect(studio_url(['job'=>$jobId]));}
 }catch(PDOException $e){$error='Request could not be recorded. Reference: '.report_error($e);}catch(InvalidArgumentException|RuntimeException $e){$error=$e->getMessage();}catch(Throwable $e){$error='Request failed. Reference: '.report_error($e);}
}
if(isset($_GET['file'])){if(!$client)fail_page('Sign in to view this file.',403);studio_download(is_string($_GET['file'])?$_GET['file']:'',(int)$client['id']);}
if(!$client){login_head('Your client workspace');if($error)echo '<div class="notice error" role="alert">'.esc($error).'</div>';if(!studio_ready()){echo '<p>The studio is preparing this workspace. Contact us through the website.</p>';}
elseif($invite!==''){?><p>Set a unique password to activate or recover your account. Invitations expire after 24 hours.</p><form method="post"><?=support_csrf_field()?><input type="hidden" name="action" value="activate"><input type="hidden" name="invite" value="<?=esc($invite)?>"><label>Password<input type="password" name="password" minlength="14" maxlength="72" required autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirm_password" minlength="14" maxlength="72" required autocomplete="new-password"></label><button class="btn gold">Set password →</button></form><?php }
else{?><p>View your projects, messages and design reviews.</p><form method="post"><?=support_csrf_field()?><input type="hidden" name="action" value="login"><label>Email<input type="email" name="email" required maxlength="190" autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn gold">Sign in →</button></form><p class="hint">Need access or a password reset? Ask the studio to issue a new private invitation link.</p><?php }login_foot();exit;}
if($jobId){try{$job=studio_job($jobId,(int)$client['id']);}catch(InvalidArgumentException){if(support_current())support_record('portal.view','project',(string)$jobId,'denied');fail_page('Project not found or access denied.',404);}}
if(support_current())support_record('portal.view',$jobId?'project':'client',(string)($jobId?:$client['id']));
site_head('Your Client Workspace','portal');support_banner();?><section class="page-hero compact"><div class="container"><span class="eyebrow">YOUR PROJECT. ALL IN ONE PLACE.</span><h1>Welcome, <span class="gold-text"><?=esc($client['name'])?>.</span></h1><div class="button-row"><a class="btn outline" href="<?=esc(studio_url())?>">All projects</a><?php if(!support_current()):?><form method="post"><?=support_csrf_field()?><input type="hidden" name="action" value="logout"><button class="btn outline">Sign out</button></form><?php endif;?></div></div></section><section class="section"><div class="container"><?php show_flash();if($error)echo '<div class="notice error" role="alert">'.esc($error).'</div>';
if(!support_current()&&support_ready()){ $policy=one('SELECT allowed FROM '.table('support_clients').' WHERE client_id=?',[$client['id']]);echo '<p class="hint">'.((int)($policy['allowed']??0)===1?'Authorized staff may access this portal for support. Staff sessions are audited and their messages are labeled Studio.':'Staff support portal access is restricted for this account.').'</p>'; }
if(!$jobId){?><div class="workspace-grid"><?php $jobs=all('SELECT * FROM '.table('studio_jobs').' WHERE client_id=? ORDER BY id DESC LIMIT 100',[$client['id']]);foreach($jobs as $j):?><article class="workspace-card"><span class="workspace-status"><?=esc(studio_stages()[$j['stage']]??$j['stage'])?></span><h2><?=esc($j['title'])?></h2><p><?=nl2br(esc($j['summary']))?></p><a class="btn gold" href="<?=esc(studio_url(['job'=>$j['id']]))?>">Open project →</a></article><?php endforeach;if(!$jobs)echo '<p>Your projects will appear here after the studio adds them.</p>';?></div><?php }
else{try{$job=studio_job($jobId,(int)$client['id']);}catch(InvalidArgumentException){http_response_code(404);echo '<p>Project not found or access denied.</p>';site_foot(false);exit;}
?><div class="workspace-card"><span class="workspace-status"><?=esc(studio_stages()[$job['stage']]??$job['stage'])?></span><h2><?=esc($job['title'])?></h2><p><?=nl2br(esc($job['summary']))?></p><h3>Milestones</h3><div class="prose"><?=nl2br(esc($job['milestones']))?></div></div><div class="workspace-grid"><div><h2>Designs & proposals</h2><?php $versions=all('SELECT * FROM '.table('studio_versions').' WHERE job_id=? ORDER BY id DESC LIMIT 100',[$jobId]);$seen=[];foreach($versions as $v):$latest=!isset($seen[$v['kind']]);$seen[$v['kind']]=true;?><article class="workspace-version"><span class="eyebrow"><?=esc($v['kind'])?> / VERSION <?=(int)$v['version_no']?></span><h3><?=esc($v['title'])?></h3><div class="prose"><?=esc($v['body'])?></div><?php if($v['preview_url']):?><p><a class="btn outline" href="<?=esc($v['preview_url'])?>" target="_blank" rel="noopener noreferrer">Open design preview ↗</a></p><?php endif;?><p class="workspace-status"><?=esc(!$latest&&$v['decision']==='pending'?'Superseded':$v['decision'])?></p><?php if($latest&&$v['decision']==='pending'&&!support_current()):?><form method="post"><?=support_csrf_field()?><input type="hidden" name="action" value="decision"><input type="hidden" name="version" value="<?=(int)$v['id']?>"><label>Decision<select name="choice"><option value="changes">Request changes</option><option value="approved">Approve this version</option></select></label><label>Feedback<textarea name="feedback" maxlength="5000" rows="3"></textarea></label><label class="check"><input type="checkbox" name="confirm" value="1" required>I confirm my decision applies to this exact version.</label><button class="btn gold">Record decision →</button></form><?php elseif($v['feedback']):?><p><?=nl2br(esc($v['feedback']))?></p><?php endif;?></article><?php endforeach;if(!$versions)echo '<p>No reviews have been published yet.</p>';?></div>
<div><article class="workspace-card"><h2>Project conversation</h2><?php foreach(all('SELECT * FROM '.table('studio_messages').' WHERE job_id=? ORDER BY id DESC LIMIT 100',[$jobId]) as $m):?><div class="workspace-message"><small><?=esc($m['author_type']==='admin'?'Studio':'Client')?> · <?=esc($m['created_at'])?> UTC</small><?=esc($m['body'])?></div><?php endforeach;?><?php if(!support_current()||support_can('support.write')):?><form method="post"><?=support_csrf_field()?><input type="hidden" name="action" value="message"><label>Your message<textarea name="body" maxlength="5000" minlength="2" required rows="4"></textarea></label><button class="btn gold">Send message →</button></form><?php else:?><p>Support messages require separate write permission.</p><?php endif;?></article>
<article class="workspace-card"><h2>Private project files</h2><?php foreach(all('SELECT * FROM '.table('studio_files').' WHERE job_id=? ORDER BY created_at DESC',[$jobId]) as $f):?><p><?php if(!support_current()||support_can('support.download')):?><a href="<?=esc(studio_url(['file'=>$f['id']]))?>"><?=esc($f['original_name'])?> ↓</a><?php else:?><?=esc($f['original_name'])?> · Download permission required<?php endif;?> <small><?=number_format($f['bytes']/1024)?> KB</small></p><?php endforeach;?><?php if(!support_current()||support_can('support.write')):?><form method="post" enctype="multipart/form-data"><?=support_csrf_field()?><input type="hidden" name="action" value="upload"><label>PDF, PNG or JPEG • up to 8 MB<input name="document" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label><button class="btn outline">Upload privately ↑</button></form><?php endif;?><p class="hint">Do not upload passwords or payment-card details. Files are private downloads, not public portfolio media.</p></article></div></div>
<div class="workspace-card"><h2>Invoices & payment instructions</h2><p>Payments are arranged with the studio. This release does not collect cards, run recurring charges or provision hosting.</p><?php foreach(all('SELECT * FROM '.table('studio_invoices').' WHERE job_id=? ORDER BY id DESC',[$jobId]) as $i):?><div class="workspace-version"><span class="workspace-status"><?=esc($i['status'])?></span><h3><?=esc($i['reference'].' · '.$i['title'])?></h3><strong>$<?=number_format($i['amount_cents']/100,2)?> USD</strong><p><?=nl2br(esc($i['instructions']))?></p><?php if($i['status']==='paid'):?><p>Receipt recorded by the studio on <?=esc($i['paid_at'])?> UTC.</p><?php endif;?></div><?php endforeach;?></div>
<?php }?></div></section><?php site_foot(false);
